size_t completion(Ort::Env&env,const Ort::Value&output){auto type=output.GetTensorTypeAndShapeInfo().GetElementType();size_t bytes=type==ONNX_TENSOR_ELEMENT_DATA_TYPE_FLOAT?4:type==ONNX_TENSOR_ELEMENT_DATA_TYPE_FLOAT16?2:0;if(!bytes)throw std::runtime_error("completion dtype");Ort::MemoryInfo gpu{"WebGPU_Buffer",OrtDeviceAllocator,0,OrtMemTypeDefault};auto cpu=Ort::MemoryInfo::CreateCpu(OrtArenaAllocator,OrtMemTypeDefault);const int64_t one[]={1};uint32_t storage=0;auto src=Ort::Value::CreateTensor(gpu,const_cast<void*>(output.GetTensorRawData()),bytes,one,1,type);auto dst=Ort::Value::CreateTensor(cpu,&storage,bytes,one,1,type);const OrtValue*s[]={src};OrtValue*d[]={dst};Ort::ThrowOnError(Ort::GetApi().CopyTensors(env,s,d,nullptr,1));return bytes;}
