   std::fprintf(stderr,"SEGMENT_DONE ref=%d sid=%zu inputs=%zu outputs=%zu carry=%zu carry_B=%zu fences=%zu captured=%d pool=0 child_local_released=1\n",ref,sid,ins.size(),outs.size(),carry.size(),B,fence_count,int(models[sid].second));
