bool PersistentFullMvsGpu::Download(const ResidentFrameLease&lease,std::array<std::vector<float>,4>*host,std::string*err){try{if(!state_||!host)throw std::runtime_error("missing state/destination");auto s=state_;std::lock_guard<std::mutex>g(s->mutex);if(!s->owns(lease))throw std::runtime_error("stale/foreign output lease");for(size_t k=0;k<4;++k){(*host)[k].resize(s->pixels());auto v=Ort::Value::CreateTensor<float>(s->cpu,(*host)[k].data(),s->pixels(),s->output_shapes[k].data(),s->output_shapes[k].size());transfer(*s->env,s->outputs[k],v);++s->counters.output_downloads;}return true;}catch(std::exception&e){if(err)*err=e.what();return false;}}
bool PersistentFullMvsGpu::DownloadInto(const ResidentFrameLease&lease,float*const host[4],size_t n,std::string*err){try{if(!state_||!host)throw std::runtime_error("missing state/destination");auto s=state_;std::lock_guard<std::mutex>g(s->mutex);if(!s->owns(lease)||n!=s->pixels())throw std::runtime_error("stale lease/output size");for(size_t k=0;k<4;++k){if(!host[k])throw std::runtime_error("null output plane");auto v=Ort::Value::CreateTensor<float>(s->cpu,host[k],n,s->output_shapes[k].data(),s->output_shapes[k].size());transfer(*s->env,s->outputs[k],v);++s->counters.output_downloads;}return true;}catch(std::exception&e){if(err)*err=e.what();return false;}}
bool PersistentFullMvsGpu::Release(ResidentFrameLease*lease,std::string*err){try{if(!state_||!lease)throw std::runtime_error("missing state/lease");auto s=state_;std::lock_guard<std::mutex>g(s->mutex);if(!s->owns(*lease))throw std::runtime_error("stale/foreign/double output release");s->live=false;s->pinned_features.clear();s->aux.erase(lease->reference);s->trim_rgb();s->material_log("lease_release_bindings_cleared");++s->counters.leases_released;lease->owner_.reset();lease->reference=-1;return true;}catch(std::exception&e){if(err)*err=e.what();return false;}}
ResidentCounters PersistentFullMvsGpu::Counters()const{if(!state_)return {};std::lock_guard<std::mutex>g(state_->mutex);auto c=state_->counters;c.cached_images=state_->images.size();c.cached_feature_views=state_->disk?size_t(std::count_if(state_->slot_photos.begin(),state_->slot_photos.end(),[](int v){return v>=0;})):state_->features.size();c.cached_reference_aux=state_->aux.size();return c;}
std::vector<ResidentFeedView> PersistentFullMvsGpu::FeedViews(const ResidentFrameLease&l)const{if(!state_)return {};std::lock_guard<std::mutex>g(state_->mutex);return state_->owns(l)?state_->feeds:std::vector<ResidentFeedView>{};}
const OrtEnv* PersistentFullMvsGpu::EnvironmentHandle(const ResidentFrameLease&l)const{if(!state_)return nullptr;std::lock_guard<std::mutex>g(state_->mutex);return state_->owns(l)?static_cast<const OrtEnv*>(*state_->env):nullptr;}
